import java.io.*;
import java.util.*;

public class CF1342E extends PrintWriter {
	CF1342E() { super(System.out, true); }
	Scanner sc = new Scanner(System.in);
	public static void main(String[] $) {
		CF1342E o = new CF1342E(); o.main(); o.flush();
	}

	static final int MD = 998244353;
	int[] ff, gg;
	long power(int a, int k) {
		if (k == 0)
			return 1;
		long p = power(a, k >> 1);
		p = p * p % MD;
		if ((k & 1) == 1)
			p = p * a % MD;
		return p;
	}
	long ch(int n, int k) {
		return (long) ff[n] * gg[k] % MD * gg[n - k] % MD;
	}
	void main() {
		int n = sc.nextInt();
		long k_ = sc.nextLong();
		if (k_ >= n) {
			println(0);
			return;
		}
		int c = n - (int) k_;
		ff = new int[n + n];
		gg = new int[n + n];
		for (int f = 1, i = 0; i < n + n; i++) {
			gg[i] = (int) power(ff[i] = f, MD - 2);
			f = (int) ((long) f * (i + 1) % MD);
		}
		long ans = 0;
		for (int a = 1; a <= c; a++) {
			long x = power(a, n) * ch(c, a) % MD;
			ans += (c - a) % 2 == 0 ? x : -x;
		}
		if ((ans %= MD) < 0)
			ans += MD;
		ans = ans * ch(n, c) % MD;
		if (k_ > 0)
			ans = ans * 2 % MD;
		println(ans);
	}
}

